from pathlib import Path
import json
P=Path(__file__).resolve().parent
DATA=json.loads((P/'oltp_metadata.json').read_text())
template=r'''<!doctype html>
<html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OLTP — 33 bảng · 6 hệ thống</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#19324b;font:14px system-ui,sans-serif}header{height:76px;padding:14px 24px;display:flex;align-items:center;gap:22px;background:#142b47;color:white}h1{font-size:20px;margin:0 0 4px}header p{margin:0;color:#bad1ec;font-size:12px}.tools{margin-left:auto;display:flex;gap:8px}button,select{font:inherit;padding:9px 13px;border:1px solid #ccd6e4;border-radius:8px;background:white;color:#19324b;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #f59e0b}nav{height:58px;display:flex;align-items:center;gap:10px;padding:8px 20px;background:white;border-bottom:1px solid #dce3ed;overflow:auto}nav button{white-space:nowrap;border-left:5px solid var(--c)}#canvas{position:relative;height:calc(100dvh - 176px);overflow:hidden;touch-action:none;background-image:radial-gradient(#d0d9e8 .8px,transparent .8px);background-size:20px 20px;cursor:grab}#canvas.panning{cursor:grabbing}svg{position:absolute;top:0;left:0;transform-origin:0 0;user-select:none;overflow:visible}.group-head,.table-head{cursor:move}.column{cursor:pointer}.column:hover rect{fill:#e2eaff}.edge{fill:none;stroke:#9baabd;stroke-width:1.7;opacity:.6;pointer-events:none}.edge.focus{stroke:#ef6c26;stroke-width:3.5;opacity:1}.edge.dim{opacity:.07}.table.dim{opacity:.25}.table.selected .table-outline{stroke:#ef6c26;stroke-width:3}.group-body{fill-opacity:.07;stroke-width:2}.table-outline{fill:white;stroke:#cad5e2;stroke-width:1.3}footer{height:42px;display:flex;gap:15px;align-items:center;padding:8px 20px;background:white;border-top:1px solid #dce3ed;font-size:12px}#status{flex:1}#scale{font-variant-numeric:tabular-nums}a{color:#2563eb}@media(max-width:700px){header{padding:10px 12px;height:95px;gap:8px}h1{font-size:16px}.tools{flex-wrap:wrap;gap:4px}.tools button{padding:7px}nav{padding:8px}#canvas{height:calc(100dvh - 195px)}footer{padding:7px 10px}header p{max-width:230px}}
</style>
<header><div><h1>OLTP — 33 bảng · 6 hệ thống</h1><p>Schema snapshot 09/11/2026 · 282 cột · 56 khóa ngoại vật lý · Bản độc lập, không phải drawSQL</p></div><div class="tools"><button id="minus" aria-label="Thu nhỏ">−</button><button id="fit">Vừa màn hình</button><button id="plus" aria-label="Phóng to">+</button><button id="clear">Bỏ chọn</button></div></header>
<nav aria-label="Sáu hệ thống" id="systems"></nav><main id="canvas" aria-label="Sơ đồ OLTP tương tác"><svg id="schema" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="33 bảng OLTP chia thành đúng 6 nhóm hệ thống, có đủ cột và quan hệ FK"><title>OLTP: 33 bảng thuộc 6 hệ thống</title><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7Z" fill="#9baabd"/></marker></defs><g id="groups"></g><g id="edges"></g><g id="tables"></g></svg></main>
<footer><span id="status" aria-live="polite">Kéo nền để di chuyển · Cuộn để zoom · Kéo tiêu đề nhóm/bảng · Bấm cột để xem liên kết</span><span id="scale"></span><span>PK: khóa chính · FK: khóa ngoại · ?: nullable</span></footer>
<script id="data" type="application/json">__DATA__</script>
<script>
(()=>{'use strict';const D=JSON.parse(document.getElementById('data').textContent),N='http://www.w3.org/2000/svg',svg=document.getElementById('schema'),view=document.getElementById('canvas'),gp=document.getElementById('groups'),ep=document.getElementById('edges'),tp=document.getElementById('tables'),status=document.getElementById('status');
const labels=['Catalog & Seller','Khách hàng & Đơn hàng','Kho vận','Marketing','Web Analytics','Tài chính'];
const groupModel=[],tableModel={},w=370,rh=27,head=45;
function el(tag,attrs={},parent){let e=document.createElementNS(N,tag);for(let[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(parent)parent.append(e);return e}
function text(parent,x,y,value,size=17,weight=400,color='#28425d'){const e=el('text',{x,y,'font-size':size,'font-weight':weight,fill:color,'font-family':'system-ui, sans-serif'},parent);e.textContent=value;return e}
const places=[[60,60,2],[1180,60,3],[2780,60,3],[60,null,2],[2780,null,2],[1180,null,2]],stack={};
D.groups.forEach(([name,color,names],i)=>{let[x,y,nc]=places[i];if(y===null)y=(stack[x]||60)+95;let ys=Array(nc).fill(100),width=nc*w+(nc-1)*95+100;const g={name,color,names,x,y,width,height:0,index:i};groupModel.push(g);for(let name of names){let col=ys.indexOf(Math.min(...ys)),t=D.tables[name],h=head+t.columns.length*rh+35;tableModel[name]={name,group:i,x:50+col*(w+95),y:ys[col],w,h,t};ys[col]+=h+75}g.height=Math.max(...ys)-25;stack[x]=y+g.height;let n=el('g',{'data-group':i},gp);el('rect',{class:'group-body',width:g.width,height:g.height,rx:18,fill:color,stroke:color},n);let h=el('g',{class:'group-head','data-drag':'group','data-key':i},n);el('rect',{width:g.width,height:58,rx:16,fill:color},h);el('rect',{y:30,width:g.width,height:28,fill:color},h);text(h,22,38,`${i+1}. ${labels[i]} · ${names.length} bảng`,23,600,'white');g.node=n;let btn=document.createElement('button');btn.style.setProperty('--c',color);btn.textContent=labels[i]+' · '+names.length;btn.onclick=()=>focusGroup(g);document.getElementById('systems').append(btn)});
const fks=new Set(D.relationships.map(r=>r.from+'.'+r.column));
for(let m of Object.values(tableModel)){const g=groupModel[m.group],n=el('g',{class:'table','data-table':m.name},tp);el('rect',{class:'table-outline',width:w,height:m.h,rx:10},n);let h=el('g',{class:'table-head','data-drag':'table','data-key':m.name},n);el('rect',{width:w,height:head,rx:10,fill:g.color},h);el('rect',{y:25,width:w,height:20,fill:g.color},h);text(h,15,30,m.name,18,600,'white');m.t.columns.forEach((c,i)=>{let row=el('g',{class:'column','data-col':c.name,'data-owner':m.name},n);let y=head+i*rh;el('rect',{x:1,y,width:w-2,height:rh,fill:i%2?'#f6f9fd':'white'},row);const pk=m.t.pk.includes(c.name),fk=fks.has(m.name+'.'+c.name);text(row,10,y+19,pk&&fk?'PK/FK':pk?'PK':fk?'FK':'',10,600,g.color);let nam=text(row,49,y+19,c.name,14,pk?600:400);let typ=c.type.replace('timestamp without time zone','timestamp').replace('character varying','varchar').replace('numeric','decimal');text(row,w-12,y+19,typ+(c.nullable?' ?':''),12,400,'#62758b').setAttribute('text-anchor','end');let title=el('title',{},row);title.textContent=`${m.name}.${c.name}: ${c.type}; ${c.nullable?'nullable':'NOT NULL'}${pk?'; PK':''}${fk?'; FK':''}`;row.addEventListener('click',()=>select(m.name,c.name))});let pkText=m.t.pk.length?'PK ('+m.t.pk.join(', ')+')':'Không có PK khai báo';let p=text(n,12,m.h-12,pkText,11,400,'#60738a');if(pkText.length>48){p.textContent=pkText.slice(0,47)+'…';el('title',{},p).textContent=pkText}m.node=n}
const paths=D.relationships.map((r,i)=>({r,path:el('path',{class:'edge','marker-end':'url(#arrow)','data-fk':i},ep)}));
function xy(m){let g=groupModel[m.group];return{x:g.x+m.x,y:g.y+m.y}}
function draw(){for(let g of groupModel)g.node.setAttribute('transform',`translate(${g.x},${g.y})`);for(let m of Object.values(tableModel)){let p=xy(m);m.node.setAttribute('transform',`translate(${p.x},${p.y})`)}for(let {r,path} of paths){let a=tableModel[r.from],b=tableModel[r.to],p=xy(a),q=xy(b),ai=a.t.columns.findIndex(c=>c.name===r.column),bi=b.t.columns.findIndex(c=>c.name===r.target),sy=p.y+head+ai*rh+rh/2,ey=q.y+head+bi*rh+rh/2;let sx,ex,mid;if(p.x===q.x){sx=p.x;ex=q.x;mid=sx-30}else{sx=p.x+(q.x>p.x?w:0);ex=q.x+(q.x>p.x?0:w);mid=(sx+ex)/2}path.setAttribute('d',`M${sx},${sy} H${mid} V${ey} H${ex}`)}}draw();
let scale=.3,ox=30,oy=30,drag=null;
function transform(){svg.style.transform=`translate(${ox}px,${oy}px) scale(${scale})`;document.getElementById('scale').textContent=Math.round(scale*100)+'%'}
function world(){return{w:Math.max(...groupModel.map(g=>g.x+g.width))+60,h:Math.max(...groupModel.map(g=>g.y+g.height))+60}}
function fit(){let b=world();svg.setAttribute('width',b.w);svg.setAttribute('height',b.h);scale=Math.min((view.clientWidth-40)/b.w,(view.clientHeight-40)/b.h);ox=(view.clientWidth-b.w*scale)/2;oy=(view.clientHeight-b.h*scale)/2;transform()}
function zoom(k,cx=view.clientWidth/2,cy=view.clientHeight/2){let ns=Math.max(.08,Math.min(2.2,scale*k));ox=cx-(cx-ox)*ns/scale;oy=cy-(cy-oy)*ns/scale;scale=ns;transform()}
function focusGroup(g){scale=Math.min(1,(view.clientWidth-60)/g.width,(view.clientHeight-60)/g.height);ox=(view.clientWidth-g.width*scale)/2-g.x*scale;oy=(view.clientHeight-g.height*scale)/2-g.y*scale;transform();status.textContent=labels[g.index]+' — '+g.names.join(', ')}
function select(name,col){let hits=paths.filter(e=>(e.r.from===name&&(!col||e.r.column===col))||(e.r.to===name&&(!col||e.r.target===col))),related=new Set([name]);hits.forEach(e=>{related.add(e.r.from);related.add(e.r.to)});for(let e of paths){e.path.classList.toggle('focus',hits.includes(e));e.path.classList.toggle('dim',!hits.includes(e))}for(let m of Object.values(tableModel)){m.node.classList.toggle('selected',m.name===name);m.node.classList.toggle('dim',!related.has(m.name))}status.textContent=hits.length?hits.map(e=>`${e.r.from}.${e.r.column} → ${e.r.to}.${e.r.target}`).join(' | '):`${name}${col?'.'+col:''}: không có FK vật lý khai báo`;}
document.getElementById('clear').onclick=()=>{paths.forEach(e=>e.path.setAttribute('class','edge'));Object.values(tableModel).forEach(m=>m.node.setAttribute('class','table'));status.textContent='33 bảng · 6 hệ thống · 56 FK vật lý'};
view.addEventListener('wheel',e=>{e.preventDefault();const r=view.getBoundingClientRect();zoom(Math.exp(-e.deltaY*.001),e.clientX-r.left,e.clientY-r.top)},{passive:false});
view.addEventListener('pointerdown',e=>{if(e.button!==0)return;const hit=e.target.closest('[data-drag]');if(hit){let kind=hit.dataset.drag,key=hit.dataset.key,model=kind==='group'?groupModel[+key]:tableModel[key];drag={kind,model,sx:e.clientX,sy:e.clientY,x:model.x,y:model.y};}else if(!e.target.closest('.column')){drag={kind:'pan',sx:e.clientX,sy:e.clientY,x:ox,y:oy};view.classList.add('panning')}else return;view.setPointerCapture(e.pointerId)});
view.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.sx,dy=e.clientY-drag.sy;if(drag.kind==='pan'){ox=drag.x+dx;oy=drag.y+dy;transform()}else{let m=drag.model;m.x=drag.x+dx/scale;m.y=drag.y+dy/scale;if(drag.kind==='table'){let g=groupModel[m.group];m.x=Math.max(20,Math.min(g.width-m.w-20,m.x));m.y=Math.max(75,Math.min(g.height-m.h-20,m.y))}draw()}});
view.addEventListener('pointerup',()=>{drag=null;view.classList.remove('panning')});view.addEventListener('pointercancel',()=>{drag=null;view.classList.remove('panning')});document.getElementById('fit').onclick=fit;document.getElementById('plus').onclick=()=>zoom(1.25);document.getElementById('minus').onclick=()=>zoom(.8);window.addEventListener('resize',fit);fit();
window.schemaSummary={tables:Object.keys(tableModel).length,groups:groupModel.length,columns:Object.values(tableModel).reduce((a,m)=>a+m.t.columns.length,0),fks:paths.length};
})();
</script></html>'''
(P/'OLTP_33_TABLES_6_SYSTEMS.html').write_text(template.replace('__DATA__',json.dumps(DATA,ensure_ascii=False).replace('</','<\\/')))
print(P/'OLTP_33_TABLES_6_SYSTEMS.html')
